class Solution {
public:
    TreeNode* recoverFromPreorder(string traversal) {
        int i = 0, n = traversal.size();
        vector<pair<int, TreeNode*>> st;
        TreeNode* root = nullptr;
        while (i < n) {
            int depth = 0;
            while (i < n && traversal[i] == '-') { depth++; i++; }
            int val = 0;
            while (i < n && traversal[i] != '-') { val = val * 10 + (traversal[i] - '0'); i++; }
            TreeNode* node = new TreeNode(val);
            while (!st.empty() && st.back().first >= depth) st.pop_back();
            if (st.empty()) {
                root = node;
            } else {
                TreeNode* parent = st.back().second;
                if (!parent->left) parent->left = node;
                else parent->right = node;
            }
            st.push_back({depth, node});
        }
        return root;
    }
};
